entries[8805] = { ["name"] = "Foliant des Magieentdeckens", ["text"] = "Klassen: Magier\nBenötigt Stufe 16\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 20 verringert werden. Hält 10 Min. lang an.\nVerkaufspreis:" }
entries[8806] = { ["name"] = "Foliant der geringen Fluchaufhebung", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Fluch aufheben'.\nBefreit ein befreundetes Ziel von 1 Fluch.\nVerkaufspreis:" }
entries[8807] = { ["name"] = "Foliant des Magieverstärkens", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 20 verringert werden. Hält 10 Min. lang an.\nVerkaufspreis:" }
entries[8808] = { ["name"] = "Foliant des Manaschilds", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Blizzard' (Rang 1).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 26 * 8) Frostschaden.\nVerkaufspreis:" }
entries[8809] = { ["name"] = "Foliant des Schlafes", ["text"] = "Klassen: Magier\nBenötigt Stufe 8\nBenutzen: Lehrt 'Schlaf' (Rang 1).\nVersetzt das feindliche Ziel bis zu 20 Sek. lang in Schlaf. Jeglicher zugefügte Schaden wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel schlafen. Unzuverlässig gegen Ziele über Stufe 30.\nVerkaufspreis:" }
