entries[8886] = { ["name"] = "Foliant des Flammenstoßes VI", ["text"] = "Klassen: Magier\nBenötigt Stufe 56\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 15 Sek. lang die Bewegung des Feindes um 60% und sein Angriffstempo um 54%.\nVerkaufspreis:" }
entries[8887] = { ["name"] = "Foliant der Versengung VII", ["text"] = "Klassen: Magier\nBenötigt Stufe 58\nBenutzen: Lehrt 'Frostzauberschutz' (Rang 5).\nAbsorbiert 875 Frostschaden. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[8888] = { ["name"] = "Foliant des Kältekegels V", ["text"] = "Klassen: Magier\nBenötigt Stufe 58\nBenutzen: Lehrt 'Eisketten' (Rang 1).\nBildet eisige Ketten um den Feind, die das Ziel 15 Sek. lang am Platz festhalten.\nVerkaufspreis:" }
entries[8889] = { ["name"] = "Foliant des Manaedelsteinherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 58\nBenutzen: Lehrt 'Manaedelstein herbeizaubern'.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 390 bis 410 Mana verwendet werden kann.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nManaachat\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 28\nBenutzen: Stellt 390 bis 410 Mana wieder her. (2 Min Abklingzeit)" }
entries[8890] = { ["name"] = "Foliant des Feuerballs XI", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Feuerball' (Rang 4).\nSchleudert eine glühende Kugel hinaus, die 89 bis 122 Feuerschaden sowie 8 Sek. lang insgesamt 12 zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:" }
entries[8891] = { ["name"] = "Foliant der Eisrüstung IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Eisrüstung' (Rang 2).\nErhöht die Rüstung um 380 und den Frostwiderstand um 9. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\nVerkaufspreis:" }
entries[8892] = { ["name"] = "Foliant des Wasserherbeizauberns VII", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 4).\nZaubert 20 Flaschen Quellwasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Quellwasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt 1345 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[8893] = { ["name"] = "Foliant des Schlafes IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Frostblitz' (Rang 2).\nSchleudert einen Frostblitz auf den Feind, der 33 bis 38 Frostschaden verursacht und 6 Sek. lang das Bewegungstempo um 40% reduziert.\nVerkaufspreis:" }
entries[8894] = { ["name"] = "Foliant des Magiedämpfens V", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 20 verringert werden. Hält 10 Min. lang an.\nVerkaufspreis:" }
entries[8895] = { ["name"] = "Foliant des Blizzards VI", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Blizzard' (Rang 2).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 45 * 8) Frostschaden.\nVerkaufspreis:" }
entries[8896] = { ["name"] = "Foliant des Manaschilds VI", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Blizzard' (Rang 1).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 26 * 8) Frostschaden.\nVerkaufspreis:" }
entries[8897] = { ["name"] = "Foliant des Feuerzauberschutzes V", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Feuerzauberschutz'.\nAbsorbiert 165 Feuerschaden. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[8898] = { ["name"] = "Foliant der arkanen Explosion IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 38\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nSchleudert arkane Geschosse auf den Feind und verursacht 3 Sek. lang alle 1 Sek. 26 Arkanschaden.\nVerkaufspreis:" }
