entries[8900] = { ["name"] = "Buch der Wucherwurzeln IV", ["text"] = "Klassen: Druide\nBenötigt Stufe 38\nBenutzen:\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht 21 Sek. lang insgesamt 140 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen. Kann nur draußen verwendet werden.\nVerkaufspreis:" }
entries[8901] = { ["name"] = "Buch der heilenden Berührung VIII", ["text"] = "Klassen: Druide\nBenötigt Stufe 44\nBenutzen: Lehrt 'Heilende Berührung' (Rang 6).\nHeilt ein befreundetes Ziel um 762 bis 914.\nVerkaufspreis:" }
