entries[8918] = { ["name"] = "Buchband: Siegel des Schutzes III", ["text"] = "Klassen: Paladin\nBenötigt Stufe 30\nBenutzen: Lehrt 'Siegel des Schutzes' (Rang 2).\nEin anvisiertes Gruppenmitglied ist 8 Sek. lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein. Einmal geschützt, kann das Ziel 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden.\nVerkaufspreis:" }
