entries[8963] = { ["name"] = "Kodex der Gedankenbesänftigung", ["text"] = "Klassen: Priester\nBenötigt Stufe 20\nBenutzen: Lehrt 'Inneres Feuer' (Rang 2).\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 720 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind.\nVerkaufspreis:" }
