entries[9036] = { ["name"] = "Magiewiderstandstrank", ["text"] = "Benötigt Stufe 32\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 Min. lang um 50. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[9037] = { ["name"] = "Schrifttafel der Waffe des Felsbeißers", ["text"] = "Klassen: Schamane\nBenutzen: Lehrt 'Blitzschlag' (Rang 2).\nSchleudert einen Blitz auf das Ziel und fügt ihm 28 bis 33 Naturschaden zu.\nVerkaufspreis:" }
entries[9039] = { ["name"] = "Schrifttafel des Erdschocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Totem der Schlange' (Rang 1).\nBeschwört 30 Sek. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 9 bis 11 Punkt(e) Feuerschaden anrichtet.\nVerkaufspreis:" }
