entries[9041] = { ["name"] = "Schrifttafel des Totems der Erdbindung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Erdbindung' (Rang 1).\nBeschwört 45 Sek. lang ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt.\nVerkaufspreis:" }
entries[9043] = { ["name"] = "Schrifttafel des Totems der Steinklaue", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 1).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 50 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
entries[9044] = { ["name"] = "Schrifttafel des Erdschocks II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 13 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)\nVerkaufspreis:" }
