entries[9293] = { ["name"] = "Rezept: Magiewiderstandstrank", ["text"] = "Benötigt Alchimie (210)\nBenutzen: Lehrt Euch die Herstellung eines Magiewiderstandstranks.\nVerkaufspreis:\nMagiewiderstandstrank\nBenötigt Stufe 32\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 Min. lang um 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Khadgars Schnurrbart , Lila Lotus , Kristallphiole" }
entries[9294] = { ["name"] = "Rezept: Wildrankentrank", ["text"] = "Benötigt Alchimie (225)\nBenutzen: Lehrt Euch die Herstellung eines Wildrankentranks.\nVerkaufspreis:\nWildrankentrank\nBenötigt Stufe 35\nBenutzen: Stellt 1 bis 1500 Gesundheit und 1 bis 1500 Mana wieder her. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Wildranke , Lila Lotus , Kristallphiole" }
entries[9295] = { ["name"] = "Rezept: Unsichtbarkeitstrank", ["text"] = "Benötigt Alchimie (235)\nBenutzen: Lehrt Euch die Herstellung eines Unsichtbarkeitstranks.\nVerkaufspreis:\nUnsichtbarkeitstrank\nBenötigt Stufe 37\nBenutzen: Gewährt dem Anwender 18 Sek. lang Unsichtbarkeit. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Geisterpilz , Sonnengras , Kristallphiole" }
entries[9296] = { ["name"] = "Rezept: Arthas' Gabe", ["text"] = "Benötigt Alchimie (240)\nBenutzen: Lehrt Euch die Herstellung von Arthas' Gabe.\nVerkaufspreis:\nArthas' Gabe\nBenötigt Stufe 38\nBenutzen: Erhöht den Schattenwiderstand um 10. Wenn ein Feind den Benutzer trifft, besteht eine Chance von 30%, dass der angreifende Feind mit einer Krankheit infiziert wird, die seinen erlittenen Schaden 3 Min. lang um 8 erhöht. Hält 30 Min. lang an. Wächterelixier. (Procchance: 30%) (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Arthas' Tränen , Blindkraut , Kristallphiole" }
entries[9297] = { ["name"] = "Rezept: Elixier der Traumvision", ["text"] = "Benötigt Alchimie (240)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Traumvision.\nVerkaufspreis:\nElixier der Traumvision\nBenötigt Stufe 38\nBenutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Lila Lotus (3), Kristallphiole" }
entries[9298] = { ["name"] = "Rezept: Elixier der Riesen", ["text"] = "Benötigt Alchimie (245)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Riesen.\nVerkaufspreis:\nElixier der Riesen\nBenötigt Stufe 38\nBenutzen: Erhöht Eure Stärke 1 Stunde lang um 25. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sonnengras , Gromsblut , Kristallphiole" }
