entries[9303] = { ["name"] = "Rezept: Stein der Weisen", ["text"] = "Benötigt Alchimie (225)\nBenutzen: Lehrt Euch die Herstellung eines Steins der Weisen.\nVerkaufspreis:\nStein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\n+5 Beweglichkeit\n+5 Ausdauer\n+5 Intelligenz\n+5 Willenskraft\nBenötigt Stufe 35\nBenötigt Alchimie (200)\n\"Erforderlich für alchimistische Transmutation.\"\nVerkaufspreis:\nBenötigt Eisenbarren (4), Schwarzes Vitriol , Lila Lotus (4), Feuerblüte (4)" }
